    # Initialize the dynamic programming table with zeros
    dp_table = [[0] * N for _ in range(N)]

    # Iterate through the input grid values and update the dynamic programming table
    for i in range(len(grid_values)):
        x, y, value = grid_values[i]
        dp_table[y][x] = value

    # Find the maximum sum of values collected on two paths
    max_sum = 0
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                continue
            path_1 = dp_table[i][j]
            for k in range(i + 1, N):
                path_2 = dp_table[k][j]
                max_sum = max(max_sum, path_1 + path_2)
            for k in range(j + 1, N):
                path_2 = dp_table[i][k]
                max_sum = max(max_sum, path_1 + path_2)

