def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    """
    Optimize the placement of aisles in a classroom to minimize the amount of chatting between students.

    Args:
        M (int): The number of rows in the classroom.
        N (int): The number of columns in the classroom.
        K (int): The number of horizontal aisles to add.
        L (int): The number of vertical aisles to add.
        D (int): The number of chatting pairs in the classroom.
        chatting_pairs (list of tuples): A list of tuples, each containing the positions (Xi, Yi) and (Pi, Qi) of a chatting pair.

    Returns:
        (str, str): Two space-separated strings representing the optimal row and column indices for the aisles.

    The function works by counting the number of chatting pairs that can be separated by adding an aisle in each possible position.
    It then selects the most effective positions for aisles, aiming to separate as many chatting pairs as possible.
    """

    def count_separable_chatting_pairs():
        """
        Count the number of chatting pairs that can be separated by the aisles.
        """
        separable_chatting_pairs = 0
        for (xi, yi, pi, qi) in chatting_pairs:
            if xi < M and yi < N:
                separable_chatting_pairs += 1
        return separable_chatting_pairs

    def pick_aisle_positions():
        """
        Pick the most effective positions for the aisles.
        """
        possible_horizontal_aisle_positions = []
        for i in range(M):
            for j in range(N):
                if i + K <= M and j + L <= N:
                    possible_horizontal_aisle_positions.append((i, j))

        possible_vertical_aisle_positions = []
        for i in range(M):
            for j in range(N):
                if i + L <= M and j + K <= N:
                    possible_vertical_aisle_positions.append((i, j))

        # Count the number of separable chatting pairs at each possible position
        horizontal_aisle_effectiveness = [0] * len(possible_horizontal_aisle_positions)
        vertical_aisle_effectiveness = [0] * len(possible_vertical_aisle_positions)
        for i, position in enumerate(possible_horizontal_aisle_positions):
            for (xi, yi, pi, qi) in chatting_pairs:
                if xi < M and yi < N:
                    if position[0] <= xi <= position[0] + K and position[1] <= yi <= position[1] + L:
                        horizontal_aisle_effectiveness[i] += 1
        for i, position in enumerate(possible_vertical_aisle_positions):
            for (xi, yi, pi, qi) in chatting_pairs:
                if xi < M and yi < N:
                    if position[0] <= xi <= position[0] + L and position[1] <= yi <= position[1] + K:
                        vertical_aisle_effectiveness[i] += 1

        # Select the most effective aisle positions based on the effectiveness score
        effectiveness_score = [horizontal_aisle_effectiveness[i] + vertical_aisle_effectiveness[i] for i in range(len(horizontal_aisle_effectiveness))]
        effective_aisle_positions = [possible_horizontal_aisle_positions[i] for i in range(len(possible_horizontal_aisle_positions)) if effectiveness_score[i] == max(effectiveness_score)]

        # Return the row and column indices of the most effective aisle positions
        return " ".join([str(position[0]) for position in effective_aisle_positions]), " ".join([str(position[1]) for position in effective_aisle_positions])

    # Count the number of separable chatting pairs and select the most effective aisle positions
    separable_chatting_pairs = count_separable_chatting_pairs()
    if separable_chatting_pairs > 0:
        return pick_aisle_positions()
