    if n < k * x or k < 1 or x < 1:
        return 0
    if n == k * x:
        return 1
    if k == 1:
        return n // x + 1
    count = 0
    for i in range(1, k):
        count += count_partitions(n - i * x, k - 1, x)
    return count + count_partitions(n - k * x, 1, x)
```
